param([Parameter(Mandatory=$true)][string]$OutputPath,[Parameter(Mandatory=$true)][string]$TaskSpecPath)
$ErrorActionPreference='Stop';$root=[IO.Path]::GetFullPath((Split-Path -Parent $PSScriptRoot));$output=[IO.Path]::GetFullPath($OutputPath);$specPath=[IO.Path]::GetFullPath($TaskSpecPath)
foreach($path in @($output,$specPath)){if(-not$path.StartsWith($root+[IO.Path]::DirectorySeparatorChar,[StringComparison]::OrdinalIgnoreCase)){throw 'GC1_PATH_OUTSIDE_PROJECT'}}
$spec=Get-Content -LiteralPath $specPath -Raw -Encoding UTF8|ConvertFrom-Json;$tasks=@($spec.tasks);if($tasks.Count-lt1){throw 'GC1_EMPTY_RUNTIME_TASK_SET'};$seen=@{}
foreach($task in $tasks){$handle=([string]$task.source_handle).ToUpperInvariant();$type=([string]$task.segment_type).ToUpperInvariant();$index=[int]$task.segment_index;if($handle-notmatch'^[0-9A-F]+$'-or$type-notin@('ARC','LINE')-or$index-lt0){throw 'GC1_INVALID_RUNTIME_TASK'};$key="$handle/$type/$index";if($seen.ContainsKey($key)){throw "GC1_DUPLICATE_RUNTIME_TASK:$key"};$seen[$key]=$true}
$base=& (Join-Path $PSScriptRoot 'build_full_scope_runtime_ordinary_v1.ps1') -OutputPath $output -TaskSpecPath $specPath;if([string]$base.status-cne'PASS'){throw 'GC1_ORDINARY_BASE'}
$text=[IO.File]::ReadAllText($output,[Text.Encoding]::UTF8);$start=$text.LastIndexOf('(defun cx:dp4-run-one',[StringComparison]::Ordinal);$finish=$text.IndexOf('(defun cx:fb-run-one',$start,[StringComparison]::Ordinal);if($start-lt0-or$finish-le$start){throw 'GC1_DISPATCH_NOT_FOUND'}
$dispatch=$text.Substring($start,$finish-$start);$pattern='\(cx:sp2-create-candidate\s+entity segment expected-style pick target-ucs effective-offset\)';if(([regex]::Matches($dispatch,$pattern)).Count-ne1){throw 'GC1_ORDINARY_FALLBACK_CALL_COUNT'};$dispatch=[regex]::Replace($dispatch,$pattern,'(cx:ha1-create-candidate entity segment expected-style pick target-ucs effective-offset)',1);$text=$text.Substring(0,$start)+$dispatch+$text.Substring($finish)
$autorun=$text.LastIndexOf('(c:CXTDIMARCFULLBATCH)',[StringComparison]::Ordinal);if($autorun-lt0){throw 'GC1_AUTORUN_NOT_FOUND'}
$endpoint=[IO.File]::ReadAllText((Join-Path $PSScriptRoot 'tdimarc_native_generation_endpoint_matched_helper_generic_v1.lsp'),[Text.Encoding]::UTF8)
$promotion=[IO.File]::ReadAllText((Join-Path $PSScriptRoot 'tdimarc_native_generation_dynamic_candidate_promotion_v1.lsp'),[Text.Encoding]::UTF8).Replace('(defun cx:ha1-create-candidate','(defun cx:gcp1-create-candidate')
$chain=[IO.File]::ReadAllText((Join-Path $PSScriptRoot 'tdimarc_native_generation_candidate_chain_v1.lsp'),[Text.Encoding]::UTF8);$modules=$endpoint.Trim()+[Environment]::NewLine+[Environment]::NewLine+$promotion.Trim()+[Environment]::NewLine+[Environment]::NewLine+$chain.Trim()+[Environment]::NewLine+[Environment]::NewLine;$text=$text.Substring(0,$autorun)+$modules+$text.Substring($autorun);[IO.File]::WriteAllText($output,$text,[Text.UTF8Encoding]::new($false))
$final=[IO.File]::ReadAllText($output,[Text.Encoding]::UTF8);if($final.Contains('cx:ha1-exact-target-p',[StringComparison]::Ordinal)){throw 'GC1_BOARD_DISPATCH_PRESENT'};foreach($token in @('GENERIC_ENDPOINT_MATCHED_HELPER_V1','GENERIC_DYNAMIC_CANDIDATE_PROMOTION_V1','PROMOTED_TO_SURVIVOR','cx:gcp1-create-candidate','cx:gc1-rank2-p')){if(-not$final.Contains($token,[StringComparison]::Ordinal)){throw "GC1_TOKEN:$token"}}
if(([regex]::Matches($final,'(?m)^\(c:CXTDIMARCFULLBATCH\)\s*$')).Count-ne1){throw 'GC1_AUTORUN_COUNT'};$lexical=& (Join-Path $PSScriptRoot 'assert_autolisp_lexical_balance_v1.ps1') -LispPath $output;if([string]$lexical.status-cne'PASS'-or[int]$lexical.final_depth-ne0){throw 'GC1_LEXICAL'}
[pscustomobject]@{status='PASS';task_count=$tasks.Count;ordinary_route='UNCHANGED';fallback_chain='RUNTIME_ENDPOINT_MATCH_THEN_DYNAMIC_NATIVE_GRIP_PROMOTION';known_failure_literals=0;source_geometry_mutation=0;lexical_balance='PASS';retry_count=0;sha256=(Get-FileHash -LiteralPath $output -Algorithm SHA256).Hash}
